import { ExportType } from "../../../wasm_module";
import { getFiles, readFile, sendFiles, Send } from "./dataTransfer";
import { JsJsonType, parseJson, stringifyJson } from "../../../jsjson";
import { ModuleControllerType } from "../../../wasm_init";
import { MapNodes } from "./map_nodes";
import { CallbackId } from "../../types";

/// One DOM event, turned into at most one call into wasm.
///
/// `send` is bound to the callback id at registration, so a handler never needs to know it.
type Handler = (event: Event, send: Send) => void;

const notify: Handler = (_event, send) => {
    send(undefined);
};

const notifyPreventDefault: Handler = (event, send) => {
    event.preventDefault();
    send(undefined);
};

/// Wasm decides: a truthy reply means the default was not wanted.
const notifyPreventIfTrue: Handler = (event, send) => {
    if (send(undefined)) {
        event.preventDefault();
    }
};

/// What the handler in wasm asked of the browser: the flags of a `ClickEvent`, a `WheelEvent` or
/// a `PointerEvent`. Only a `PointerEvent` asks to capture the pointer, and gives `capture` for it.
const applyFlags = (event: Event, flags: JsJsonType, capture?: () => void) => {
    // Check if flags is an object (JsJson Object type)
    if (flags !== null && typeof flags === 'object' && !Array.isArray(flags)) {
        if ('stop_propagation' in flags && flags['stop_propagation'] === true) {
            event.stopPropagation();
        }
        if ('prevent_default' in flags && flags['prevent_default'] === true) {
            event.preventDefault();
        }
        if (capture && 'capture_pointer' in flags && flags['capture_pointer'] === true) {
            try {
                capture();
            } catch (error) {
                // A pointer that's up already, f. ex. a finger in `pointerup`.
                console.warn('capture_pointer', error);
            }
        }
    }
};

/// Wasm gets the modifier keys and replies with the `ClickEvent` flags. The browser's default
/// action - following a link, submitting a form, toggling a checkbox - goes ahead unless the
/// handler asked to prevent it.
export const click: Handler = (event, send) => {
    if (!(event instanceof MouseEvent)) {
        throw Error('#click');
    }

    // Payload order MUST match the Rust decoder `ClickEvent::from_driver`.
    applyFlags(event, send([
        event.altKey,
        event.ctrlKey,
        event.shiftKey,
        event.metaKey,
    ]));
};

/// Wasm replies with the `WheelEvent` flags: the page scrolls, or zooms, unless the handler
/// asked to prevent it. The pointer goes relative to the element with the listener, the one
/// whose size comes along, rather than to the child under the pointer as `offsetX` would.
export const wheel: Handler = (event, send) => {
    const target = event.currentTarget;

    if (!(event instanceof WheelEvent) || !(target instanceof Element)) {
        throw Error('#wheel');
    }

    const rect = target.getBoundingClientRect();

    // Payload order MUST match the Rust decoder `WheelEvent::from_driver`.
    applyFlags(event, send([
        event.deltaX,
        event.deltaY,
        event.deltaZ,
        event.deltaMode,
        event.clientX - rect.left,
        event.clientY - rect.top,
        rect.width,
        rect.height,
        event.altKey,
        event.ctrlKey,
        event.shiftKey,
        event.metaKey,
    ]));
};

/// The pointer events, all four of them. Wasm replies with the `PointerEvent` flags, and with
/// `capture_pointer` the events of this pointer go to the element with the listener until it's
/// released. The pointer goes relative to that element, as for the wheel.
export const pointer: Handler = (event, send) => {
    const target = event.currentTarget;

    if (!(event instanceof PointerEvent) || !(target instanceof Element)) {
        throw Error('#pointer');
    }

    const rect = target.getBoundingClientRect();

    // Payload order MUST match the Rust decoder `PointerEvent::from_driver`.
    applyFlags(event, send([
        event.pointerId,
        event.pointerType,
        event.isPrimary,
        event.button,
        event.buttons,
        event.clientX - rect.left,
        event.clientY - rect.top,
        rect.width,
        rect.height,
        event.altKey,
        event.ctrlKey,
        event.shiftKey,
        event.metaKey,
    ]), () => {
        target.setPointerCapture(event.pointerId);
    });
};

/// Where the content of the element is scrolled to, and how big it and its visible part are.
/// A scroll has happened already, so wasm has nothing to reply.
const scrollOf = (target: Element, send: Send) => {
    // Payload order MUST match the Rust decoder `ScrollEvent::from_driver`.
    send([
        target.scrollTop,
        target.scrollLeft,
        target.scrollWidth,
        target.scrollHeight,
        target.clientWidth,
        target.clientHeight,
    ]);
};

/// The scroll of the element, read after it.
export const scroll: Handler = (event, send) => {
    const target = event.currentTarget;

    if (!(target instanceof Element)) {
        throw Error('#scroll');
    }

    scrollOf(target, send);
};

/// `input` and `change` differ only in whether a `<select>` counts as a value source. They
/// also share a warning, which stays one literal rather than two identical copies.
const readValue = (allowSelect: boolean): Handler => (event, send) => {
    const target = event.target;

    if (target instanceof HTMLInputElement
        || target instanceof HTMLTextAreaElement
        || (allowSelect && target instanceof HTMLSelectElement)) {
        send(target.value);
        return;
    }

    console.warn('event input ignore', target);
};

/// `change` of a checkbox or a radio button, with whether it is checked now - its `value` is
/// the same either way.
const changeChecked: Handler = (event, send) => {
    const target = event.target;

    if (target instanceof HTMLInputElement) {
        send(target.checked);
        return;
    }

    console.warn('changeChecked: not an input', target);
};

const changeFile: Handler = (event, send) => {
    const target = event.target;

    if (target instanceof HTMLInputElement && target.files !== null && target.files.length > 0) {
        const promises = [];

        for (let i = 0; i < target.files.length; i++) {
            const file = target.files[i];
            if (file !== undefined) {
                promises.push(readFile(file));
            }
        }

        if (promises.length > 0) {
            sendFiles(promises, send, 'changeFile ->');
        }

        target.value = '';
        return;
    }

    console.warn('changeFile: not a file input or no files', target);
};

const drop: Handler = (event, send) => {
    event.preventDefault();

    if (event instanceof DragEvent) {
        if (event.dataTransfer === null) {
            console.error('dom -> drop -> dataTransfer null');
        } else {
            const files = getFiles(event.dataTransfer.items);

            if (files.length) {
                sendFiles(files, send, 'callback_drop -> promise.all -> ');
            } else {
                console.error('No files to send');
            }
        }
    } else {
        console.warn('event drop ignore', event);
    }
};

const keydown: Handler = (event, send) => {
    if (event instanceof KeyboardEvent) {
        const result = send([
            event.key,
            event.code,
            event.altKey,
            event.ctrlKey,
            event.shiftKey,
            event.metaKey
        ]);

        if (result === true) {
            event.preventDefault();
            event.stopPropagation();
        }

        return;
    }

    console.warn('keydown ignore', event);
};

/// The events of a `<video>` or an `<audio>` behind one `on_media`. The list MUST match
/// `MediaEventKind::ALL` in `media_event.rs`.
const MEDIA_EVENTS = [
    'loadedmetadata', 'durationchange', 'timeupdate', 'progress', 'play', 'playing', 'pause',
    'waiting', 'seeked', 'ended', 'volumechange', 'error',
];

/// Up to where the media is in the browser from the current position on.
const bufferedAhead = (media: HTMLMediaElement): number => {
    const { buffered, currentTime } = media;

    for (let i = 0; i < buffered.length; i++) {
        if (buffered.start(i) <= currentTime && currentTime <= buffered.end(i)) {
            return buffered.end(i);
        }
    }

    return currentTime;
};

/// What happened to a `<video>` or an `<audio>`, with its whole state after - the length is
/// `null` while unknown (`NaN`) and for a stream with no end (`Infinity`).
const media = (element: HTMLMediaElement, type: string, send: Send) => {
    // Payload order MUST match the Rust decoder `MediaEvent::from_driver`.
    send([
        type,
        element.currentTime,
        Number.isFinite(element.duration) ? element.duration : null,
        element.paused,
        element.ended,
        element.muted,
        element.volume,
        bufferedAhead(element),
    ]);
};

/// A message from the page in a frame: where it came from and what it said, as far as JSON can
/// hold it - a `Date` becomes text, bytes (a `Uint8Array`) a list of numbers as a `Vec<u8>` reads
/// them, and what JSON has no room for at all (a `BigInt`, a cycle, `undefined`) - `null`. Which
/// frame it came from, [`CallbackManager.add`] checks.
const message = (event: MessageEvent, send: Send) => {
    let data: JsJsonType;

    try {
        // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- `JSON.stringify` gives `undefined` for `undefined` or a function, whatever its type says
        data = parseJson(stringifyJson(event.data) ?? 'null');
    } catch {
        data = null;
    }

    // Payload order MUST match the Rust decoder `MessageEvent::from_driver`.
    send([event.origin, data]);
};

/// Messages that came to the window before the app was there to hear them. The wasm starts
/// after the page's `load`, which waits for the frames, so on a page rendered on the server
/// a frame has often said what it had to - f. ex. a widget how tall it wants to be - before its
/// `on_message` was added. They wait here until the first batch is in place, and an `on_message`
/// added in it gets the ones from its frame first.
let earlyMessages: Array<MessageEvent> | null = [];

export const keepEarlyMessage = (event: MessageEvent) => {
    earlyMessages?.push(event);
};

if (typeof window !== 'undefined') {
    window.addEventListener('message', keepEarlyMessage);
}

/// The event names are wire strings from Rust (`dom/dom_element.rs`), so each is spelled out
/// exactly once here. `hook_keydown`, `change_file` and `change_checked` are vertigo-internal
/// names, remapped to real DOM events where the listener is attached. `intersect`, `media` and
/// `message` aren't one DOM event of the element, so `CallbackManager.add` takes them on its own.
const HANDLERS: Record<string, Handler> = {
    click,
    submit: notifyPreventDefault,
    input: readValue(false),
    change: readValue(true),
    blur: notify,
    mousedown: notifyPreventIfTrue,
    mouseup: notifyPreventIfTrue,
    mouseenter: notify,
    mouseleave: notify,
    keydown,
    hook_keydown: keydown,
    drop,
    load: notifyPreventDefault,
    change_file: changeFile,
    change_checked: changeChecked,
    wheel,
    scroll,
    pointerdown: pointer,
    pointermove: pointer,
    pointerup: pointer,
    pointercancel: pointer,
};

/// The DOM event behind a wire name: `change_file` and `change_checked` are the `change` event
/// with a payload of their own.
const domEventName = (event_name: string): string =>
    event_name === 'change_file' || event_name === 'change_checked' ? 'change' : event_name;

export class CallbackManager {
    private readonly getWasm: () => ModuleControllerType<ExportType>;
    private callbacks: Map<CallbackId, (data: Event) => void>;
    // IntersectionObserver does not use addEventListener, so its observers are
    // tracked separately (keyed by callback_id) for disconnect on remove.
    private observers: Map<CallbackId, IntersectionObserver>;

    public constructor(getWasm: () => ModuleControllerType<ExportType>) {
        this.getWasm = getWasm;
        this.callbacks = new Map();
        this.observers = new Map();
    }

    public add(nodes: MapNodes, id: number, event_name: string, callback_id: CallbackId) {
        if (event_name === 'intersect') {
            this.intersectAdd(nodes, id, callback_id);
            return;
        }

        const send: Send = (value) => this.wasmCallback(callback_id, value);

        const callback = (event: Event) => {
            // Looked up per fire rather than once at registration, which keeps the previous
            // behaviour for an unsupported name: the listener is still attached and the
            // complaint is logged each time the event arrives.
            const handler = HANDLERS[event_name];

            if (handler === undefined) {
                console.error(`No support for the event ${event_name}`);
                return;
            }

            handler(event, send);
        };

        if (this.callbacks.has(callback_id)) {
            console.error(`There was already a callback added with the callback_id=${callback_id}`);
            return;
        }

        if (event_name === 'media') {
            const element = nodes.get('callback_add', id);

            // `dom!` doesn't let it through, but `DomElement::on_media` and an `AttrGroup` don't
            // know the element's name.
            if (!(element instanceof HTMLMediaElement)) {
                throw Error(`on_media: expected id=${id} as HTMLMediaElement`);
            }

            const listener = (event: Event) => media(element, event.type, send);
            this.callbacks.set(callback_id, listener);
            MEDIA_EVENTS.forEach((name) => element.addEventListener(name, listener, false));

            // On a page rendered on the server the media loads before the wasm starts, so what
            // it said by then comes after the batch, which wasm is still in the middle of sending.
            // 1 is `HAVE_METADATA`.
            if (element.error !== null) {
                queueMicrotask(() => media(element, 'error', send));
            } else if (element.readyState >= 1) {
                queueMicrotask(() => media(element, 'loadedmetadata', send));
            }
            return;
        }

        if (event_name === 'message') {
            // A message comes to the window, from any frame or window that has a reference to
            // it - only the ones from the page in this frame go on.
            const frame = nodes.get('callback_add', id);

            // Nothing else has a page of its own to hear from. `dom!` doesn't let it through, but
            // `DomElement::on_message` and an `AttrGroup` don't know the element's name.
            if (!(frame instanceof HTMLIFrameElement)) {
                throw Error(`on_message: expected id=${id} as HTMLIFrameElement`);
            }

            const fromFrame = (event: Event) => {
                if (event instanceof MessageEvent && event.source !== null && event.source === frame.contentWindow) {
                    message(event, send);
                }
            };

            this.callbacks.set(callback_id, fromFrame);
            window.addEventListener('message', fromFrame, false);

            // After the batch, which wasm is still in the middle of sending
            const early = [...(earlyMessages ?? [])];
            if (early.length > 0) {
                queueMicrotask(() => early.forEach(fromFrame));
            }
            return;
        }

        this.callbacks.set(callback_id, callback);

        if (event_name === 'hook_keydown') {
            document.addEventListener('keydown', callback, false);
        } else {
            const node = nodes.get('callback_add', id);
            // A wheel listener isn't passive, so that `WheelEvent::prevent_default` can keep the
            // page from scrolling: browsers make one on `<body>` passive unless told.
            node.addEventListener(domEventName(event_name), callback, event_name === 'wheel' ? { passive: false } : false);

            // An element hydration adopted keeps where it was scrolled to before the wasm started
            // - by the visitor, or by the caret in a `<textarea>` - and no scroll will tell of it.
            // That goes after the batch, which wasm is still in the middle of sending. Only the
            // first batch adopts, and a new element is at the start, so later ones don't look -
            // a read of the scroll lays the page out.
            if (event_name === 'scroll' && nodes.hasInitNodes()) {
                queueMicrotask(() => {
                    if (node instanceof Element && (node.scrollTop !== 0 || node.scrollLeft !== 0)) {
                        scrollOf(node, send);
                    }
                });
            }
        }
    }

    public remove(nodes: MapNodes, id: number, event_name: string, callback_id: CallbackId) {
        if (event_name === 'intersect') {
            this.intersectRemove(callback_id);
            return;
        }

        const callback = this.callbacks.get(callback_id);
        this.callbacks.delete(callback_id);

        if (callback === undefined) {
            console.error(`The callback is missing with the id=${callback_id}`);
            return;
        }

        if (event_name === 'media') {
            const element = nodes.get('callback_remove', id);
            MEDIA_EVENTS.forEach((name) => element.removeEventListener(name, callback));
        } else if (event_name === 'message') {
            window.removeEventListener('message', callback);
        } else if (event_name === 'hook_keydown') {
            document.removeEventListener('keydown', callback);
        } else {
            const node = nodes.get('callback_remove', id);
            node.removeEventListener(domEventName(event_name), callback);
        }
    }

    /// The first batch is in place: the frames of the page have their `on_message` already.
    public forgetEarlyMessages() {
        if (earlyMessages !== null) {
            window.removeEventListener('message', keepEarlyMessage);
            earlyMessages = null;
        }
    }

    private wasmCallback(callback_id: CallbackId, value: JsJsonType): JsJsonType {
        return this.getWasm().wasmCommand({
            CallbackCall: {
                callback_id,
                value: value
            }
        });
    }

    private intersectAdd(nodes: MapNodes, id: number, callback_id: CallbackId) {
        if (this.observers.has(callback_id)) {
            console.error(`There was already an intersect observer added with the callback_id=${callback_id}`);
            return;
        }

        const node = nodes.getNode('callback_add', id);

        const observer = new IntersectionObserver((entries) => {
            for (const entry of entries) {
                // Payload order MUST match the Rust decoder get_intersection_event.
                this.wasmCallback(callback_id, [
                    entry.isIntersecting,
                    entry.intersectionRatio,
                    entry.boundingClientRect.top,
                    entry.boundingClientRect.bottom,
                    entry.boundingClientRect.height,
                ]);
            }
        });

        observer.observe(node);
        this.observers.set(callback_id, observer);
    }

    private intersectRemove(callback_id: CallbackId) {
        const observer = this.observers.get(callback_id);
        this.observers.delete(callback_id);

        if (observer === undefined) {
            console.error(`The intersect observer is missing with the id=${callback_id}`);
            return;
        }

        observer.disconnect();
    }
}
