import { BufferCursor } from "./buffer_cursor";
import { encoder } from "./text";

const JsJsonConst = {
    True: 1,
    False: 2,
    Null: 3,
    Undefined: 4,
    String: 5,
    Number: 6,
    List: 7,
    Object: 8,
    Vec: 9,
} as const;

export type JsJsonType = boolean | null | undefined | string | number | Uint8Array<ArrayBuffer> | Array<JsJsonType> | { [key: string]: JsJsonType };

/// `JSON.parse`, typed.
export const parseJson = (text: string): JsJsonType =>
    // eslint-disable-next-line @typescript-eslint/no-unsafe-return -- every value JSON can hold is a JsJsonType
    JSON.parse(text);

/// `JSON.stringify` of a JsJsonType, or of whatever a message from a frame holds. Bytes - a
/// `Uint8Array`, from a `Vec<u8>` field - become a list of numbers, as vertigo-cli writes them for
/// a fetch made while rendering on the server and as `AutoJsJson` reads them back. `JSON.stringify`
/// alone makes them an object keyed by index.
export const stringifyJson = (value: unknown): string =>
    JSON.stringify(value, (_key, item: unknown) => item instanceof Uint8Array ? Array.from(item) : item);

/// Sizing pass. Walks the value to work out how large a wasm block to ask for, before
/// `saveJsJsonToBufferItem` walks it again to fill that block.
///
/// Two walks looks like waste, and collapsing them into a single pass over a growable JS
/// buffer was tried. It is slower, and worth recording why so it is not tried again: writing
/// through `BufferCursor` goes straight into wasm linear memory with nothing allocated on the
/// JS side, whereas a growable sink costs a buffer plus a DataView per message and then a full
/// copy of the payload into wasm at the end. Measured on dom-bench over three interleaved
/// rounds, the single-pass version cost a mean of 4% and up to 16% on the callback-heavy
/// workloads (`flush-min`, `editor-toggle-bold`, `editor-keystroke-patch`), to save 169 bytes.
///
/// The invariant the two passes have to keep - that this returns exactly the number of bytes
/// the writer goes on to use - is what `jsjson.test.ts` pins.
export const jsJsonGetSize = (value: JsJsonType): number => {
    if (value === true || value === false || value === null || value === undefined) {
        return 1;
    }

    if (typeof value === 'string') {
        return 1 + 4 + encoder.encode(value).length;
    }

    if (typeof value === 'number') {
        return 1 + 8;
    }

    if (value instanceof Uint8Array) {
        return 1 + 4 + value.length;
    }

    if (Array.isArray(value)) {
        let sum = 1 + 4;
        for (const item of value) {
            sum += jsJsonGetSize(item);
        }
        return sum;
    }

    if (typeof value === 'object') {
        let sum = 1 + 2;
        for (const [key, propertyValue] of Object.entries(value)) {
            sum += 4 + encoder.encode(key).length;
            sum += jsJsonGetSize(propertyValue);
        }
        return sum;
    }

    throw new Error(`jsJsonGetSize: Unknown type ${typeof value}`);
};

export const jsJsonDecodeItem = (buffer: BufferCursor): JsJsonType => {
    const typeId = buffer.getByte();

    if (typeId === JsJsonConst.True) {
        return true;
    }

    if (typeId === JsJsonConst.False) {
        return false;
    }

    if (typeId === JsJsonConst.Null) {
        return null;
    }

    if (typeId === JsJsonConst.Undefined) {
        return undefined;
    }

    if (typeId === JsJsonConst.String) {
        return buffer.getString();
    }

    if (typeId === JsJsonConst.Number) {
        return buffer.getF64();
    }

    if (typeId === JsJsonConst.List) {
        const count = buffer.getU32();
        const list: Array<JsJsonType> = [];

        for (let i = 0; i < count; i++) {
            list.push(jsJsonDecodeItem(buffer));
        }

        return list;
    }

    if (typeId === JsJsonConst.Object) {
        const count = buffer.getU16();
        const obj: { [key: string]: JsJsonType } = {};

        for (let i = 0; i < count; i++) {
            const key = buffer.getString();
            const value = jsJsonDecodeItem(buffer);
            obj[key] = value;
        }

        return obj;
    }

    if (typeId === JsJsonConst.Vec) {
        // `.slice()`, and it has to be: `getBuffer` hands back a view straight into wasm
        // linear memory, and the caller frees the block it points into before the decoded
        // value is used (see `dom_access` in `wasm_module.ts`). Every other variant decodes
        // into JS values that own their data; this is the only one that would otherwise
        // escape as a window onto memory the allocator is free to reuse or grow away from.
        return buffer.getBuffer().slice();
    }

    throw new Error(`jsJsonDecodeItem: Unknown type id ${typeId}`);
};

export const saveJsJsonToBufferItem = (value: JsJsonType, buffer: BufferCursor): void => {
    if (value === true) {
        buffer.setByte(JsJsonConst.True);
        return;
    }

    if (value === false) {
        buffer.setByte(JsJsonConst.False);
        return;
    }

    if (value === null) {
        buffer.setByte(JsJsonConst.Null);
        return;
    }

    if (value === undefined) {
        buffer.setByte(JsJsonConst.Undefined);
        return;
    }

    if (typeof value === 'string') {
        buffer.setByte(JsJsonConst.String);
        buffer.setString(value);
        return;
    }

    if (typeof value === 'number') {
        buffer.setByte(JsJsonConst.Number);
        buffer.setF64(value);
        return;
    }

    if (value instanceof Uint8Array) {
        buffer.setByte(JsJsonConst.Vec);
        buffer.setBuffer(value);
        return;
    }

    if (Array.isArray(value)) {
        buffer.setByte(JsJsonConst.List);
        buffer.setU32(value.length);

        for (const item of value) {
            saveJsJsonToBufferItem(item, buffer);
        }

        return;
    }

    if (typeof value === 'object') {
        const entries = Object.entries(value);

        buffer.setByte(JsJsonConst.Object);
        buffer.setU16(entries.length);

        for (const [key, propertyValue] of entries) {
            buffer.setString(key);
            saveJsJsonToBufferItem(propertyValue, buffer);
        }

        return;
    }

    throw new Error(`saveJsJsonToBufferItem: Unknown type ${typeof value}`);
};
